import hashlib
import os
import time
import struct
from typing import Optional, Tuple, List

# Role-based access control system with bitfield permissions
# Each user has a 32-bit permission mask stored as signed int
# Bit positions: 0=read, 1=write, 2=delete, 3=admin, 4=audit, 5=export

PERM_READ = 0
PERM_WRITE = 1
PERM_DELETE = 2
PERM_ADMIN = 3
PERM_AUDIT = 4
PERM_EXPORT = 5

class PermissionStore:
    """Stores user permissions as compact bitfields."""

    def __init__(self):
        self._store = {}  # user_id -> permission_bytes (4 bytes, big-endian signed)
        self._sessions = {}  # session_token -> (user_id, expiry)
        self._audit_log = []

    def create_user(self, user_id: str, initial_perms: List[int]) -> bool:
        """Create user with initial permission set."""
        if not user_id or len(user_id) > 64:
            return False
        if user_id in self._store:
            return False
        # Validate permission bits
        mask = 0
        for perm in initial_perms:
            if perm < 0 or perm > 31:
                return False
            mask |= (1 << perm)
        # Store as signed 32-bit big-endian
        self._store[user_id] = struct.pack('>i', mask)
        self._audit_log.append(('create', user_id, mask, time.time()))
        return True

    def create_session(self, user_id: str) -> Optional[str]:
        """Create authenticated session for user."""
        if user_id not in self._store:
            return None
        token = hashlib.sha256(os.urandom(32)).hexdigest()
        self._sessions[token] = (user_id, time.time() + 3600)
        return token

    def _get_user_from_session(self, session_token: str) -> Optional[str]:
        """Validate session and return user_id."""
        if session_token not in self._sessions:
            return None
        user_id, expiry = self._sessions[session_token]
        if time.time() > expiry:
            del self._sessions[session_token]
            return None
        return user_id

    def get_permission_mask(self, user_id: str) -> Optional[int]:
        """Retrieve the raw permission mask for a user."""
        if user_id not in self._store:
            return None
        raw_bytes = self._store[user_id]
        # Unpack as signed 32-bit integer
        (mask,) = struct.unpack('>i', raw_bytes)
        return mask

    def check_permission(self, session_token: str, required_perm: int) -> bool:
        """Check if the session's user has the required permission bit."""
        user_id = self._get_user_from_session(session_token)
        if user_id is None:
            return False

        mask = self.get_permission_mask(user_id)
        if mask is None:
            return False

        # Security check: validate required_perm is in valid range
        if required_perm < 0 or required_perm > 31:
            return False

        # Check if the bit is set
        return (mask >> required_perm) & 1 == 1

    def grant_permission(self, session_token: str, target_user: str, perm_bit: int) -> bool:
        """Grant a permission to target user. Requires admin permission."""
        if not self.check_permission(session_token, PERM_ADMIN):
            return False

        if target_user not in self._store:
            return False

        if perm_bit < 0 or perm_bit > 31:
            return False

        current_mask = self.get_permission_mask(target_user)
        new_mask = current_mask | (1 << perm_bit)
        self._store[target_user] = struct.pack('>i', new_mask)

        user_id = self._get_user_from_session(session_token)
        self._audit_log.append(('grant', user_id, target_user, perm_bit, time.time()))
        return True

    def revoke_permission(self, session_token: str, target_user: str, perm_bit: int) -> bool:
        """Revoke a permission from target user. Requires admin permission."""
        if not self.check_permission(session_token, PERM_ADMIN):
            return False

        if target_user not in self._store:
            return False

        if perm_bit < 0 or perm_bit > 31:
            return False

        current_mask = self.get_permission_mask(target_user)
        new_mask = current_mask & ~(1 << perm_bit)
        self._store[target_user] = struct.pack('>i', new_mask)

        user_id = self._get_user_from_session(session_token)
        self._audit_log.append(('revoke', user_id, target_user, perm_bit, time.time()))
        return True


class ResourceServer:
    """Serves protected resources based on permission checks."""

    def __init__(self, perm_store: PermissionStore):
        self._perm_store = perm_store
        self._resources = {}  # resource_id -> (content, required_perm_bit)

    def add_resource(self, resource_id: str, content: str, required_perm: int):
        """Register a resource with its required permission level."""
        if required_perm < 0 or required_perm > 31:
            raise ValueError("Invalid permission bit")
        self._resources[resource_id] = (content, required_perm)

    def access_resource(self, session_token: str, resource_id: str) -> Tuple[bool, Optional[str]]:
        """Attempt to access a resource. Returns (success, content_or_none)."""
        if resource_id not in self._resources:
            return (False, None)

        content, required_perm = self._resources[resource_id]

        if self._perm_store.check_permission(session_token, required_perm):
            return (True, content)

        return (False, None)

    def bulk_check_access(self, session_token: str, resource_ids: List[str]) -> dict:
        """Check access for multiple resources at once."""
        results = {}
        for rid in resource_ids:
            if rid in self._resources:
                _, required_perm = self._resources[rid]
                results[rid] = self._perm_store.check_permission(session_token, required_perm)
            else:
                results[rid] = False
        return results
